 public UUID id=UUID.randomUUID(),owner,target,radarId;public String ownerName="",status="OFF",radarState="NO_RADAR",targetName="";public float yaw,pitch=25,heat,targetDistance;public boolean enabled,automatic=true,overheated;public int priorities=38,shots;public final NonNullList<ItemStack>ammo=NonNullList.withSize(8,ItemStack.EMPTY);private long nextShot,lastAction=-10,lastSync,lastMoveSound;private int burst;private boolean removing,shooting;private float fromYaw,fromPitch=25,toYaw,toPitch=25;private long poseTick,lastShot=-100;
 public AdcBlockEntity(BlockPos p,BlockState s){super(AddonBlockEntities.ADC01.get(),p,s);}public Direction facing(){return getBlockState().getValue(AdcBlock.FACING);}public ServerLevel defenseLevel(){return(ServerLevel)level;}public UUID defenseId(){return id;}public UUID defenseOwner(){return owner;}public String defenseOwnerName(){return ownerName;}public Vec3 defensePosition(){return AdcGeometry.MODEL.radar(worldPosition,facing(),yaw,pitch,sensorYaw(0),sensorPitch(0));}public float sensorYaw(float partial){return targetName.isEmpty()&&level!=null?(float)(java.lang.Math.sin((level.getGameTime()+partial)/55d)*45):0;}public float sensorPitch(float partial){return targetName.isEmpty()?5:viewPitch(partial);}
