 public boolean permitted(ServerPlayer p){return level==p.level()&&!p.isSpectator()&&p.isAlive()&&!InjuryServer.cannotOperate(p)&&DefenseData.allowed(defenseLevel(),owner,ownerName,p)&&level.mayInteract(p,worldPosition);}
 public boolean canOperate(ServerPlayer p){if(!permitted(p))return false;var anchor=AdcGeometry.MODEL.anchor(worldPosition,facing(),"Interaction_Anchor",yaw,pitch,0);return p.getEyePosition().distanceToSqr(anchor)<=36&&AdcBlock.clip(this,p.getEyePosition(),anchor).getType()==HitResult.Type.MISS;}
