 public float viewYaw(float partial){return fromYaw+net.minecraft.util.Mth.wrapDegrees(toYaw-fromYaw)*progress(partial);}public float viewPitch(float partial){return fromPitch+(toPitch-fromPitch)*progress(partial);}private float progress(float partial){return level==null?1:net.minecraft.util.Mth.clamp((level.getGameTime()-poseTick+partial)/4f,0,1);}public float recoil(float partial){return level==null?0:(float)(.055*java.lang.Math.max(0,1-(level.getGameTime()-lastShot+partial)/4));}public Vec3 muzzle(){return AdcGeometry.MODEL.anchor(worldPosition,facing(),"Muzzle_Anchor",yaw,pitch,recoil(0));}public Vec3 direction(){return AdcGeometry.MODEL.forward(facing(),yaw,pitch);}
 public void whitelist(ServerPlayer actor,String value,boolean remove){if(!canOperate(actor)||level.getGameTime()-lastAction<3)return;lastAction=level.getGameTime();value=value.trim();UUID who=null;try{who=UUID.fromString(value);}catch(IllegalArgumentException ignored){}var player=actor.getServer().getPlayerList().getPlayerByName(value);if(player!=null)who=player.getUUID();if(who==null)for(var entry:whitelist.entrySet())if(entry.getValue().equalsIgnoreCase(value)){who=entry.getKey();break;}if(who==null){actor.displayClientMessage(net.minecraft.network.chat.Component.literal("Enter an online player name or UUID."),true);return;}if(remove)whitelist.remove(who);else if(whitelist.size()<64||whitelist.containsKey(who))whitelist.put(who,player==null?value:player.getScoreboardName());target=null;DefenseData.get(defenseLevel()).release(id);changed();}
 private void writeWhitelist(CompoundTag n){var list=new ListTag();whitelist.forEach((uuid,name)->{var entry=new CompoundTag();entry.putUUID("UUID",uuid);entry.putString("Name",name);list.add(entry);});n.put("Whitelist",list);}
 private void readWhitelist(CompoundTag n){whitelist.clear();for(var value:n.getList("Whitelist",10)){var entry=(CompoundTag)value;if(entry.hasUUID("UUID")&&whitelist.size()<64)whitelist.put(entry.getUUID("UUID"),entry.getString("Name"));}}
 public boolean valid(Entity e){return e!=null&&!AdcTargets.protectedBy(whitelist.keySet(),defenseLevel(),e)&&AdcTargets.hostile(defenseLevel(),owner,ownerName,e,priorities)&&e.getBoundingBox().getCenter().distanceToSqr(defensePosition())<=AdcConfig.RANGE.get()*AdcConfig.RANGE.get();}
 private boolean available(Entity e){return valid(e)&&!DefenseData.get(defenseLevel()).cannonAssigned(defenseLevel(),e.getUUID(),id);}
 private void refreshRadar(){var site=DefenseData.get(defenseLevel()).site(id);var before=radarId;String old=radarState;radarId=site==null?null:site.radar;var r=DefenseData.get(defenseLevel()).radar(defenseLevel(),radarId);radarState=radarId==null?"NO_RADAR":r==null?"UNLOADED":r.active()?"READY":"OFF";if(!Objects.equals(before,radarId)||!old.equals(radarState))changed();}
 boolean scanPending;
 private void scan(){scanPending=false;var data=DefenseData.get(defenseLevel());var site=data.site(id);radarId=site==null?null:site.radar;var radar=data.radar(defenseLevel(),radarId);radarState=radarId==null?"NO_RADAR":radar==null?"UNLOADED":radar.active()?"READY":"OFF";Entity selected=target==null?null:defenseLevel().getEntity(target);if(available(selected))return;target=null;data.release(id);var found=new ArrayList<Entity>();if(radar!=null&&radar.active()&&level.getGameTime()-radar.scanned<DefenseConfig.SCAN.get()*3L)for(var v:radar.contacts.subList(0,Math.min(128,radar.contacts.size()))){var n=(CompoundTag)v;var e=defenseLevel().getEntity(n.getUUID("UUID"));if(available(e))found.add(e);}if(found.isEmpty()){var center=defensePosition();long deadline=System.nanoTime()+400_000;int[] visited={0};defenseLevel().getEntities().get(net.minecraft.world.level.entity.EntityTypeTest.forClass(Entity.class),new AABB(center,center).inflate(AdcConfig.RANGE.get()),e->{if(++visited[0]>128||System.nanoTime()>deadline)return net.minecraft.util.AbortableIterationConsumer.Continuation.ABORT;if(available(e))found.add(e);return net.minecraft.util.AbortableIterationConsumer.Continuation.CONTINUE;});}found.sort(Comparator.comparingDouble(e->AdcTargets.score(defensePosition(),e,priorities)));if(!found.isEmpty()){target=found.get(0).getUUID();data.reserve(id,target,level.getGameTime());}changed();}
 private boolean visible(Entity e,Vec3 predicted){Vec3 start=muzzle().add(direction().scale(.12));if(!Hgd01Lasers.loaded(defenseLevel(),start,predicted))return false;if(AdcBlock.clip(this,start,predicted).getType()!=HitResult.Type.MISS)return false;for(var box:AdcGeometry.MODEL.boxes(worldPosition,facing(),yaw,pitch))if(box.deflate(.015).clip(start,start.add(direction().scale(.75))).isPresent())return false;return true;}
 private boolean fire(Entity e){if(shooting||AdcShell.active(defenseLevel())>=AdcConfig.MAX_SHELLS.get()||count()<AdcConfig.COST.get())return false;shooting=true;try{var shell=AddonEntities.ADC01_SHELL.get().create(level);if(shell==null)return false;var at=muzzle().add(direction().scale(.13));shell.setPos(at);shell.principal(owner,ownerName);shell.whitelist(whitelist.keySet());shell.source(id);shell.setDamage(AdcConfig.DAMAGE.get().floatValue());shell.setOwner(owner==null?null:defenseLevel().getServer().getPlayerList().getPlayer(owner));var d=direction();shell.shoot(d.x,d.y,d.z,4.5f,AdcConfig.SPREAD.get().floatValue());if(!defenseLevel().addFreshEntity(shell))return false;shell.track();int needed=AdcConfig.COST.get();for(var s:ammo){int take=java.lang.Math.min(needed,s.getCount());s.shrink(take);needed-=take;if(needed==0)break;}heat=java.lang.Math.min(100,heat+AdcConfig.HEAT.get().floatValue());if(heat>=100&&!overheated){overheated=true;sound("overheat",.65f,1);}lastShot=level.getGameTime();shots++;status="FIRING";DefenseData.get(defenseLevel()).reserve(id,e.getUUID(),level.getGameTime());if(AdcConfig.EFFECTS.get()>0)defenseLevel().sendParticles(net.minecraft.core.particles.ParticleTypes.FLAME,at.x,at.y,at.z,AdcConfig.EFFECTS.get(),.025,.025,.025,.01);sound("ah_6_cannon_fire_3p",1,1);changed();return true;}finally{shooting=false;}}
 public void sound(String key,float volume,float pitch){var event=net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.get(net.minecraft.resources.ResourceLocation.tryParse("superbwarfare:"+key));if(event!=null)level.playSound(null,worldPosition,event,net.minecraft.sounds.SoundSource.BLOCKS,volume,pitch);}
 public static void tick(Level l,BlockPos p,BlockState s,AdcBlockEntity b){if(l.isClientSide||b.removing)return;long now=l.getGameTime();if(java.lang.Math.floorMod(now+p.asLong(),AdcConfig.SCAN.get())==0)b.refreshRadar();float old=b.heat;b.heat=java.lang.Math.max(0,b.heat-AdcConfig.COOL.get().floatValue());if(b.overheated&&b.heat<=AdcConfig.RECOVER.get()){b.overheated=false;b.changed();}if(old!=b.heat&&now-b.lastSync>=10)b.changed();if(!b.enabled||!b.automatic){b.scanPending=false;b.targetName="";b.targetDistance=0;if(b.target!=null){DefenseData.get(b.defenseLevel()).release(b.id);b.target=null;}b.status(b.enabled?"IDLE":"OFF");if(old!=b.heat&&now-b.lastSync>=10)b.changed();return;}if(java.lang.Math.floorMod(now+p.asLong(),AdcConfig.SCAN.get())==0)b.scanPending=true;if(b.scanPending)AdcWorkBudget.run(b,true,b::scan);AdcWorkBudget.run(b,false,b::aimStep);}
 private void aimStep(){var b=this;var l=level;var p=worldPosition;long now=level.getGameTime();var goal=b.target==null?null:b.defenseLevel().getEntity(b.target);if(!b.available(goal)){if(b.target!=null){DefenseData.get(b.defenseLevel()).release(b.id);b.target=null;}b.targetName="";b.targetDistance=0;b.status("SEARCHING");return;}if(!b.overheated&&b.count()>=AdcConfig.COST.get())DefenseData.get(b.defenseLevel()).reserve(b.id,b.target,now);else DefenseData.get(b.defenseLevel()).release(b.id);b.targetName=goal.getName().getString();b.targetDistance=(float)b.defensePosition().distanceTo(goal.position());var lead=AdcTargets.lead(b.muzzle(),goal);var local=new org.joml.Matrix4d(AdcGeometry.world(p,b.facing())).invert().transformPosition(new org.joml.Vector3d(lead.x,lead.y,lead.z));var pivot=AdcGeometry.MODEL.bones.get(AdcGeometry.MODEL.names.get("Gun_Elevation")).pivot();local.sub(pivot);float desiredYaw=(float)java.lang.Math.toDegrees(java.lang.Math.atan2(-local.x,-local.z)),desiredPitch=(float)java.lang.Math.toDegrees(java.lang.Math.atan2(local.y,java.lang.Math.hypot(local.x,local.z)));float previous=b.yaw;b.yaw=net.minecraft.util.Mth.approachDegrees(b.yaw,desiredYaw,AdcConfig.YAW.get().floatValue());b.pitch=net.minecraft.util.Mth.approach(b.pitch,net.minecraft.util.Mth.clamp(desiredPitch,0,75),AdcConfig.PITCH.get().floatValue());if(java.lang.Math.abs(net.minecraft.util.Mth.wrapDegrees(b.yaw-previous))>.2&&now-b.lastMoveSound>=30){b.lastMoveSound=now;b.sound("turret_turn",.18f,1);}if(now-b.lastSync>=4){b.toYaw=b.yaw;b.toPitch=b.pitch;b.changed();}if(b.heat>=100&&!b.overheated){b.overheated=true;b.sound("overheat",.65f,1);b.changed();}if(b.overheated){b.status("OVERHEATED");return;}if(b.count()<AdcConfig.COST.get()){b.status("NO_AMMO");return;}if(desiredPitch<0||desiredPitch>75||b.direction().dot(lead.subtract(b.muzzle()).normalize())<.998){b.status("TRACKING");return;}if(!b.visible(goal,lead)){DefenseData.get(b.defenseLevel()).release(b.id);b.status("BLOCKED");return;}if(now<b.nextShot){b.status(b.burst==0?"PAUSE":"FIRING");return;}if(b.fire(goal)){b.status="FIRING";if(++b.burst>=AdcConfig.BURST.get()){b.burst=0;b.nextShot=now+AdcConfig.PAUSE.get();}else b.nextShot=now+AdcConfig.INTERVAL.get();}else b.status("LIMIT");}
 public boolean defenseAvailable(){return enabled&&automatic&&!overheated&&count()>=AdcConfig.COST.get()&&target==null;}public boolean defenseRequest(ServerPlayer actor,UUID goal,UUID radar){var e=defenseLevel().getEntity(goal);if(!defenseAvailable()||!valid(e)||!DefenseData.get(defenseLevel()).radarAllows(defenseLevel(),radar,id,actor,actor==null))return false;target=goal;DefenseData.get(defenseLevel()).reserve(id,target,level.getGameTime());changed();return true;}
 public void control(ServerPlayer p,int action,int slot){if(!canOperate(p)||level.getGameTime()-lastAction<3)return;lastAction=level.getGameTime();if(action==0){changed();return;}if(action==1)enabled=!enabled;else if(action==2)automatic=!automatic;else if(action==3)loadAmmo(p);else if(action==4)unloadAmmo(p);else if(action==5&&slot>=0&&slot<3){int n=(priorities>>(slot*2))&3;n=(n+1)%3;priorities=(priorities&~(3<<(slot*2)))|(n<<(slot*2));target=null;DefenseData.get(defenseLevel()).release(id);}else if(action==6){DefenseData.get(defenseLevel()).unlink(id);radarId=null;radarState="NO_RADAR";}changed();}
 private void loadAmmo(ServerPlayer p){int remaining=java.lang.Math.max(0,AdcConfig.CAPACITY.get()-count());for(var s:p.getInventory().items){if(!s.is(ammunition()))continue;for(int i=0;i<ammo.size()&&remaining>0&&!s.isEmpty();i++){var at=ammo.get(i);if(!at.isEmpty()&&!ItemStack.isSameItemSameComponents(at,s))continue;int n=java.lang.Math.min(remaining,java.lang.Math.min(s.getCount(),s.getMaxStackSize()-(at.isEmpty()?0:at.getCount())));if(n<=0)continue;if(at.isEmpty())ammo.set(i,s.split(n));else{at.grow(n);s.shrink(n);}remaining-=n;}}p.getInventory().setChanged();}
 private void unloadAmmo(ServerPlayer p){for(var stack:ammo)if(!stack.isEmpty()){var copy=stack.copy();int before=copy.getCount();p.getInventory().add(copy);stack.shrink(before-copy.getCount());}p.getInventory().setChanged();}
 public boolean removing(){return removing;}public boolean remove(ServerPlayer p,boolean drop){if(removing||p!=null&&!permitted(p))return false;removing=true;var item=new ItemStack(AddonItems.ADC01.get());var data=stateTag();data.remove("Id");data.remove("Target");data.remove("Radar");data.putBoolean("Enabled",false);var tag=DefenseItem.data(item);tag.put("Installation",data);DefenseItem.data(item,tag);DefenseData.get(defenseLevel()).remove(defenseLevel(),id);boolean old=AdcBlock.MUTATING.get();AdcBlock.MUTATING.set(true);try{for(var c:AdcGeometry.MODEL.cells){var at=AdcGeometry.MODEL.cell(worldPosition,facing(),c);if(level.hasChunkAt(at)&&level.getBlockState(at).getBlock() instanceof AdcBlock&&AdcBlock.root(at,level.getBlockState(at)).equals(worldPosition))level.removeBlock(at,false);}}finally{AdcBlock.MUTATING.set(old);}if(drop&&(p==null||!p.isCreative()))net.minecraft.world.Containers.dropItemStack(level,worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5,item);return true;}
 public CompoundTag stateTag(){return saveWithoutMetadata(level.registryAccess());}public void restore(CompoundTag n){loadWithComponents(n,level.registryAccess());target=null;enabled=false;radarId=null;nextShot=level.getGameTime()+20;}
