 @Override protected void saveAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){super.saveAdditional(n,registry);writeWhitelist(n);n.putUUID("Id",id);if(owner!=null)n.putUUID("Owner",owner);n.putString("OwnerName",ownerName);n.putBoolean("Enabled",enabled);n.putBoolean("Automatic",automatic);n.putBoolean("Overheated",overheated);n.putFloat("Heat",heat);n.putFloat("Yaw",yaw);n.putFloat("Pitch",pitch);n.putInt("Priorities",priorities);n.putLong("LastShot",lastShot);n.putString("Status",status);n.putInt("Shots",shots);n.putString("RadarState",radarState);if(radarId!=null)n.putUUID("Radar",radarId);n.putString("TargetName",targetName);n.putFloat("TargetDistance",targetDistance);net.minecraft.world.ContainerHelper.saveAllItems(n,ammo,registry);}
 @Override protected void loadAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){super.loadAdditional(n,registry);if(n.hasUUID("Id"))id=n.getUUID("Id");readWhitelist(n);owner=n.hasUUID("Owner")?n.getUUID("Owner"):null;ownerName=n.getString("OwnerName");enabled=n.getBoolean("Enabled");automatic=n.getBoolean("Automatic");overheated=n.getBoolean("Overheated");heat=net.minecraft.util.Mth.clamp(n.getFloat("Heat"),0,100);fromYaw=viewYaw(0);fromPitch=viewPitch(0);yaw=n.getFloat("Yaw");pitch=net.minecraft.util.Mth.clamp(n.getFloat("Pitch"),0,75);toYaw=yaw;toPitch=pitch;poseTick=level==null?0:level.getGameTime();if(level==null||!level.isClientSide){fromYaw=yaw;fromPitch=pitch;}priorities=n.contains("Priorities")?n.getInt("Priorities")&63:38;lastShot=n.getLong("LastShot");status=n.getString("Status");shots=n.getInt("Shots");radarId=n.hasUUID("Radar")?n.getUUID("Radar"):null;radarState=n.getString("RadarState");targetName=n.getString("TargetName");targetDistance=n.getFloat("TargetDistance");target=null;if(level!=null&&level.isClientSide){visualAmmo=n.getInt("AmmoCount");}else{for(int i=0;i<ammo.size();i++)ammo.set(i,ItemStack.EMPTY);net.minecraft.world.ContainerHelper.loadAllItems(n,ammo,registry);}}
 @Override public CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider registry){var n=stateTag();n.remove("Items");n.putInt("AmmoCount",count());return n;}@Override public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}public AABB getRenderBoundingBox(){return AdcGeometry.transform(AdcGeometry.world(worldPosition,facing()),AdcGeometry.MODEL.bounds);}
